    const lineNum = clip.highlights.length;
    // Position highlight naturally over text
    const defaultY = Math.min(0.85, 0.468 + (lineNum * 0.046));
    const newHl = {
      x: 0.235,
      y: defaultY,
      w: 0.495,
      h: 0.046,
      color: '#ffff00',
      startTime: parseFloat(relT.toFixed(2)),
      duration: 0.7
    };
