const TEMPLATE_CATEGORIES = ['All', '★ My Templates', 'Finance', 'Animations', '3D Spatial', 'Paper / Cutout', 'Transitions', 'Parallax', 'Text & Titles', 'Color & Vibe', 'Sound FX', 'Glitches'];

let currentTemplateCategory = 'All';
let templateSearchQuery = '';
let activeHoverAnimFrame = null;
let activeHoverCardEl = null;
let hoverStartTime = 0;

function switchStudioView(viewName) {
  const homeView = document.getElementById('home-templates-discovery');
  const editorView = document.getElementById('editor-workspace');
  const btnHome = document.getElementById('btn-nav-view-home');
  const btnEditor = document.getElementById('btn-nav-view-editor');

  if (viewName === 'home') {
    if (homeView) homeView.style.display = 'block';
    if (editorView) editorView.style.display = 'none';
    if (btnHome) {
      btnHome.style.background = '#8b5cf6';
      btnHome.style.color = '#fff';
      btnHome.classList.add('active');
    }
    if (btnEditor) {
      btnEditor.style.background = 'transparent';
      btnEditor.style.color = '#94a3b8';
      btnEditor.classList.remove('active');
    }
    // Hide editor-specific top bar controls on templates page
    document.querySelectorAll('.editor-only-nav').forEach(el => {
      el.style.display = 'none';
    });
    const newProjectBtn = document.getElementById('btn-templates-open-editor');
    if (newProjectBtn) newProjectBtn.style.display = 'flex';
    // Update vertical rail active tab to 'templates'
    document.querySelectorAll('.nav-rail .rail-btn').forEach(b => {
      b.classList.toggle('active', b.dataset.railTab === 'templates');
    });
    renderHomepageCategories();
    renderHomepageTemplates();
  } else {
    if (homeView) homeView.style.display = 'none';
    if (editorView) editorView.style.display = 'grid';
    if (btnHome) {
      btnHome.style.background = 'transparent';
      btnHome.style.color = '#94a3b8';
      btnHome.classList.remove('active');
    }
    if (btnEditor) {
      btnEditor.style.background = '#8b5cf6';
      btnEditor.style.color = '#fff';
      btnEditor.classList.add('active');
    }
    // Hide home-only New Project button in editor view
    const newProjectBtn = document.getElementById('btn-templates-open-editor');
    if (newProjectBtn) newProjectBtn.style.display = 'none';
    // Show editor-specific top bar controls in Studio Editor mode
    const projInfo = document.getElementById('top-project-info');
    if (projInfo) projInfo.style.display = 'flex';
    const ctxActions = document.getElementById('top-contextual-actions');
    if (ctxActions) ctxActions.style.display = 'flex';
    const saveBtn = document.getElementById('btn-save-project');
    if (saveBtn) saveBtn.style.display = 'inline-flex';
    const turnTplBtn = document.getElementById('btn-top-turn-template');
    if (turnTplBtn) turnTplBtn.style.display = 'inline-flex';
    const exportBtn = document.getElementById('btn-export');
    if (exportBtn) exportBtn.style.display = 'inline-flex';
    const topShareBtn = document.getElementById('btn-top-share-project');
    if (topShareBtn) topShareBtn.style.display = 'inline-flex';
    const div2 = document.getElementById('top-divider-2');
    if (div2) div2.style.display = 'block';
    const panelToggles = document.getElementById('top-panel-toggles');
    if (panelToggles) panelToggles.style.display = 'flex';

    // Update vertical rail active tab to 'all' (Media/Uploads) if templates was active
    const activeRail = document.querySelector('.nav-rail .rail-btn.active');
    if (!activeRail || activeRail.dataset.railTab === 'templates') {
      document.querySelectorAll('.nav-rail .rail-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.railTab === 'all');
      });
    }
    // Re-trigger layout sizing on canvas
    if (typeof renderCanvas === 'function') renderCanvas();
  }
}

function renderHomepageCategories() {
  const container = document.getElementById('home-category-pills');
  if (!container) return;

  const customTpls = getCustomTemplates();
  const customCount = customTpls.length;

  container.innerHTML = TEMPLATE_CATEGORIES.map(cat => {
    const isActive = cat === currentTemplateCategory;
    const isCustomCat = cat === '★ My Templates';
    const label = isCustomCat ? `★ My Templates (${customCount})` : cat;
    const specialClass = isCustomCat ? 'is-my-templates-pill' : '';

    return `
      <button type="button" class="home-cat-pill ${isActive ? 'active' : ''} ${specialClass}" data-cat="${cat}" style="${isCustomCat && isActive ? 'background: linear-gradient(135deg, #a855f7, #6366f1); border-color: #c084fc; color: #fff;' : isCustomCat ? 'border-color: rgba(168,85,247,0.4); color: #d8b4fe;' : ''}">
        ${label}
      </button>
    `;
  }).join('');

  container.querySelectorAll('.home-cat-pill').forEach(btn => {
    btn.addEventListener('click', (e) => {
      currentTemplateCategory = e.currentTarget.dataset.cat;
      renderHomepageCategories();
      renderHomepageTemplates();
    });
  });
}

function renderHomepageTemplates() {
  const grid = document.getElementById('home-templates-grid');
  const countEl = document.getElementById('home-templates-count');
  const headingEl = document.getElementById('home-templates-heading');
  if (!grid) return;

  // Merge user custom templates with built-in templates
  const customTemplates = getCustomTemplates();
  const allTemplates = [...customTemplates, ...EFFECT_TEMPLATES_DATA];

  const filtered = allTemplates.filter(t => {
    let matchesCat = false;
    if (currentTemplateCategory === 'All') {
      matchesCat = true;
    } else if (currentTemplateCategory === '★ My Templates') {
      matchesCat = !!t.isCustom || t.category === 'My Templates';
    } else {
      matchesCat = t.category === currentTemplateCategory || t.origCategory === currentTemplateCategory;
    }

    const query = templateSearchQuery.toLowerCase().trim();
    const titleStr = (t.title || t.name || '').toLowerCase();
    const badgeStr = (t.badge || '').toLowerCase();
    const descStr = (t.description || '').toLowerCase();
    const tagsArr = Array.isArray(t.tags) ? t.tags : [];
    const matchesSearch = !query ||
      titleStr.includes(query) ||
      badgeStr.includes(query) ||
      descStr.includes(query) ||
      tagsArr.some(tag => String(tag).toLowerCase().includes(query));

    return matchesCat && matchesSearch;
  });

  if (countEl) countEl.textContent = `${filtered.length}`;
  if (headingEl) {
    headingEl.textContent = currentTemplateCategory === 'All'
      ? 'Inspired By Your Creative Workflow'
      : currentTemplateCategory === '★ My Templates'
        ? 'My Created Templates & Custom Layouts'
        : `${currentTemplateCategory} Templates`;
  }

  if (filtered.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1 / -1; padding: 60px 20px; text-align: center; color: #64748b;">
        <svg viewBox="0 0 24 24" style="width: 38px; height: 38px; fill: none; stroke: currentColor; stroke-width: 1.5; margin: 0 auto 12px;"><path stroke-linecap="round" stroke-linejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <p style="font-size: 15px; font-weight: 600; color: #94a3b8; margin: 0;">No templates matched "${templateSearchQuery}"</p>
        <p style="font-size: 12px; margin: 6px 0 0;">Try searching for "cutout", "paper rip", "gold frame", or "parallax".</p>
      </div>
    `;
    return;
  }

  grid.innerHTML = filtered.map(t => {
    return `
      <div class="home-tpl-card" data-template-id="${t.id}">
        <div class="home-tpl-media" id="media-wrap-${t.id}">
          <img src="${(typeof window.tplGetSnapshot === 'function' && window.tplGetSnapshot(t.id)) || t.defaultImage}" alt="${t.title}" class="home-tpl-img" id="default-img-${t.id}" />
          <div class="home-tpl-overlay" style="background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.15) 60%, rgba(0,0,0,0.65) 100%);"></div>
          
          <div class="home-tpl-center-label" id="center-label-${t.id}" style="display: none !important;">
            <div style="padding: 4px 14px; border-radius: 6px; background: rgba(0,0,0,0.82); backdrop-filter: blur(8px); border: 1px solid rgba(255, 255, 255, 0.18); color: #ffffff; font-size: 10.5px; font-family: monospace; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase;">
              [ ${t.category.toUpperCase()} ]
            </div>
          </div>

          <!-- Container for dynamic Live Hover Video FX -->
          <div class="home-tpl-fx-container" id="fx-container-${t.id}" style="position: absolute; inset: 0; overflow: hidden; pointer-events: none; display: none;"></div>

          <div class="home-tpl-badge" id="badge-${t.id}">${t.badge}</div>
          <div class="home-tpl-time">${t.timeToApply}</div>

          <div class="home-tpl-play-hover" id="play-hover-${t.id}">
            <div class="home-tpl-play-circle">
              <svg viewBox="0 0 24 24" style="width: 22px; height: 22px; fill: currentColor; margin-left: 2px;"><path d="M8 5v14l11-7z"/></svg>
            </div>
          </div>
        </div>

        <div class="home-tpl-content">
          <div>
            <h4 class="home-tpl-title">${t.title}</h4>
            <p class="home-tpl-desc">${t.description}</p>
          </div>

          <div class="home-tpl-footer">
            <div style="display: flex; gap: 6px; flex-wrap: wrap;">
              ${t.tags.slice(0, 2).map(tag => `<span class="home-tpl-tag">#${tag}</span>`).join('')}
            </div>
            <div style="display: flex; align-items: center; gap: 8px;">
              <button type="button" class="home-tpl-share-btn" data-share-tpl-id="${t.id}" title="Share template preset">
                <svg viewBox="0 0 24 24" style="width: 13px; height: 13px; fill: currentColor;"><path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92 1.61 0 2.92-1.31 2.92-2.92s-1.31-2.92-2.92-2.92z"/></svg>
              </button>
              <span class="home-tpl-btn-use">
                Open FX
                <svg viewBox="0 0 24 24" style="width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.5;"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
              </span>
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');

  // Attach hover video effect listeners, share button handler, and click handler to each card
  grid.querySelectorAll('.home-tpl-card').forEach(card => {
    const tplId = card.dataset.templateId;
    const tpl = allTemplates.find(item => item.id === tplId);

    // Share button click handler
    const shareBtn = card.querySelector('.home-tpl-share-btn');
    if (shareBtn) {
      shareBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openTemplateShareModal(tplId);
      });
    }

    card.addEventListener('mouseenter', () => {
      startTemplateHoverVideo(card, tpl);
    });

    card.addEventListener('mouseleave', () => {
      stopTemplateHoverVideo(card, tpl);
    });

    card.addEventListener('click', () => {
      applySelectedHomepageTemplate(tplId);
    });
  });
}

